def get_valid_input(prompt):
    """Get a valid input from the user."""
    while True:
        try:
            user_input = input(prompt)
            tokens = user_input.split()
            if len(tokens) == 2:
                num1, operator, num2 = tokens
                return (float(num1), operator, float(num2))
            else:
                print("Invalid input. Please enter two numbers and an operator (+, -, *, /).")
        except ValueError:
            print("Invalid input. Please enter numbers and operators.")

def perform_operation(num1, operator, num2):
    """Perform the specified operation on two numbers."""
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        return num1 / num2
    else:
        raise ValueError("Invalid operator. Please use +, -, *, /.")

def main():
    num1, operator, num2 = get_valid_input("Enter two numbers and an operator: ")
    try:
        result = perform_operation(num1, operator, num2)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
